18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.samples.petclinic.util.BusinessDays;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
61	     * customerCode and registrationDate. */
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
65	    private static final int CITY_CAPACITY = 50;
66	
67	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
68	     * create is rejected once this many owners already carry today's registration date. */
69	    private static final int DAILY_REGISTRATION_LIMIT = 100;
70	
71	    /** Once more than this many owners already carry a given day's registration date, a new owner
72	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
73	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
124	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
125	        // registration date — the stored value, the per-day limit below and the membership number —
126	        // uses this adjusted date.
127	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
128	        owner.setRegistrationDate(effectiveDate);
129	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
130	        // further creates for that day with 429 Too Many Requests.
131	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
132	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
136	        // for its registration date, signalling a bulk-signup surge.
137	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
138	        // Per-city capacity: a city that already holds the maximum number of owners is full.
139	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        // The household id is derived deterministically on the owner itself (see
143	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
144	        // last name and postcode share it automatically — no linking step and no ordering to manage.
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
147	        // (normalized telephone | email-or-empty | householdId) equals an existing owner's. A
148	        // truly identical record is always rejected, independent of sharesHousehold.
149	        if (this.clinicService.isIdentityKeyInUse(owner)) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        // Household duplicate: another owner already belongs to this (last name, postcode)
153	        // household. Reject with 409 unless the caller declares the shared household via
154	        // sharesHousehold, which bypasses the block and creates this owner as a declared member.
155	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
156	        if (householdInUse && !sharesHousehold) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        // Soft "possible duplicate" detection: an existing owner shares this owner's last name and
160	        // postcode with a different telephone. A declared household member (sharesHousehold on an
161	        // in-use household) is an intentional share, not a suspected duplicate, so it is not
162	        // flagged; otherwise the create still proceeds, flagged with possibleDuplicate=true and
163	        // possibleDuplicateOf set to the matching owner id.
164	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
165	            ? null
166	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
167	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
168	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
169	        owner.setNamesakeCount(
170	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
174	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
175	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
189	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
190	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
191	        currentOwner.setCity(ownerFieldsDto.getCity());
192	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
193	        currentOwner.setLastName(ownerFieldsDto.getLastName());
194	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
195	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
196	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
197	        this.clinicService.saveOwner(currentOwner);
198	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Transactional
203	    @Override
204	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        this.clinicService.deleteOwner(owner);
210	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner == null) {
218	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	        }
220	        HttpHeaders headers = new HttpHeaders();
221	        Pet pet = petMapper.toPet(petFieldsDto);
222	        owner.setId(ownerId);
223	        pet.setOwner(owner);
224	        pet.getType().setName(null);
225	        this.clinicService.savePet(pet);
226	        PetDto petDto = petMapper.toPetDto(pet);
227	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
228	            .buildAndExpand(pet.getId()).toUri());
229	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
235	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
236	        if (currentOwner != null) {
237	            Pet currentPet = this.clinicService.findPetById(petId);
238	            if (currentPet != null) {
239	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
240	                currentPet.setName(petFieldsDto.getName());
241	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
242	                this.clinicService.savePet(currentPet);
243	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
252	        HttpHeaders headers = new HttpHeaders();
253	        Visit visit = visitMapper.toVisit(visitFieldsDto);
254	        Pet pet = new Pet();
255	        pet.setId(petId);
256	        visit.setPet(pet);
257	        this.clinicService.saveVisit(visit);
258	        VisitDto visitDto = visitMapper.toVisitDto(visit);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
260	            .buildAndExpand(visit.getId()).toUri());
261	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
262	    }
263	
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner != null) {
270	            Pet pet = owner.getPet(petId);
271	            if (pet != null) {
272	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
273	            }
274	        }
275	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	    }
277	}
