196	        if (owner == null || owner.getCustomerCode() == null) {
197	            return null;
198	        }
199	        String code = owner.getCustomerCode();
200	        int sum = 0;
201	        boolean dbl = true;
202	        for (int i = code.length() - 1; i >= 0; i--) {
203	            char c = code.charAt(i);
204	            if (c < '0' || c > '9') {
205	                continue;
206	            }
207	            int d = c - '0';
208	            if (dbl) {
209	                d *= 2;
210	                if (d > 9) {
