250	    /**
251	     * The calendar year in which {@code date}'s fiscal year ends, used as the fiscal year's name.
252	     * The fiscal year starts on 1 July, so a date in July through December belongs to the fiscal
253	     * year ending the following calendar year, while January through June belongs to the one
254	     * ending in the current calendar year.
255	     */
256	    default int fiscalYearEndYear(LocalDate date) {
257	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
258	    }
