276	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
277	     */
278	    default String formatSalutation(Owner owner) {
279	        if (owner == null) {
280	            return null;
281	        }
282	        String title = owner.getTitle();
283	        if (title == null || title.trim().isEmpty()) {
284	            return owner.getLastName();
285	        }
286	        return title + " " + owner.getLastName();
287	    }
288	
289	    /**
290	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
291	     */
292	    default String formatDisplayName(Owner owner) {
293	        if (owner == null) {
294	            return null;
295	        }
296	        return owner.getLastName() + ", " + owner.getFirstName();
297	    }
298	
299	    /**
300	     * Format an owner's initials as the upper-cased first letters of the first and last
301	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
302	     */
303	    default String formatInitials(Owner owner) {
304	        if (owner == null) {
305	            return null;
306	        }
307	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
308	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
309	    }
310	
311	    Owner toOwner(OwnerDto ownerDto);
312	
313	    @Mapping(target = "id", ignore = true)
314	    @Mapping(target = "pets", ignore = true)
315	    @Mapping(target = "namesakeCount", ignore = true)
316	    @Mapping(target = "bulkSignupWarning", ignore = true)
317	    @Mapping(target = "possibleDuplicate", ignore = true)
318	    @Mapping(target = "possibleDuplicateOf", ignore = true)
319	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
320	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
321	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
322	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
323	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
324	    Owner toOwner(OwnerFieldsDto ownerDto);
325	
326	    /**
327	     * Normalize a postal address for storage into its canonical form (see
328	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
329	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
330	     * automatic method selection, so it only runs where a mapping explicitly references it via
331	     * {@code qualifiedByName}.
332	     */
333	    @Named("normalizeAddress")
334	    default String normalizeAddress(String address) {
335	        return AddressNormalizer.normalize(address);
336	    }
337	
338	    /**
339	     * Compose the single stored/returned {@code address} from whichever address fields the request
340	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
341	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
342	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
343	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
344	     * that reads the stored address consistent regardless of which form the caller used.
345	     */
346	    default String composeAddress(OwnerFieldsDto ownerDto) {
347	        if (ownerDto == null) {
348	            return null;
349	        }
350	        String line1 = ownerDto.getAddressLine1();
351	        if (line1 != null && !line1.trim().isEmpty()) {
352	            String composed = AddressNormalizer.normalize(line1);
353	            String line2 = ownerDto.getAddressLine2();
354	            if (line2 != null && !line2.trim().isEmpty()) {
355	                composed = composed + " " + AddressNormalizer.normalize(line2);
356	            }
357	            return composed;
358	        }
359	        return AddressNormalizer.normalize(ownerDto.getAddress());
360	    }
361	
362	    /**
363	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
364	     * The requirement that a valid E.164 number can be formed is enforced separately by
365	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
366	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
367	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
368	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
369	     */
370	    @Named("normalizeTelephone")
371	    default String normalizeTelephone(String telephone) {
372	        return E164Telephone.normalize(telephone);
373	    }
374	
375	    /**
376	     * Normalize an email address for storage by lower-casing it, so it is persisted and
377	     * returned in a canonical form regardless of the casing supplied by the caller.
378	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
379	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
380	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
381	     */
382	    @Named("normalizeEmail")
383	    default String normalizeEmail(String email) {
384	        return email == null ? null : email.toLowerCase();
385	    }
386	
387	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
388	
389	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
390	
391	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
392	        OwnerPageDto ownerPageDto = new OwnerPageDto();
393	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
394	        ownerPageDto.setPage(ownerPage.getNumber());
395	        ownerPageDto.setSize(ownerPage.getSize());
396	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
397	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
398	        return ownerPageDto;
399	    }
400	}
